#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int findLucky(vector<int>& arr) {
        unordered_map<int, int> count;
        for (int n : arr) count[n]++;
        int res = -1;
        for (auto& [k, v] : count)
            if (k == v) res = max(res, k);
        return res;
    }
};
